-- Model: sat_oa_timesheet_curr
-- Description: Current active record for SAT_OA_TIMESHEET using ROW_NUMBER()
-- Generated by: bv pipeline generate transform with custom template
-- Satellite Type: SAT_ON_HUB
-- Parent: hub HUB_TIMESHEET

WITH RANKED_RECORDS AS (
SELECT
    TIMESHEET_HKEY,  -- hash key
    LOAD_DATE AS _CURRENT_ACTIVE_TIMESTAMP, -- used: LOAD_DATE
    -- Satellite Attributes
    ID                  ,  -- is_business_key
    LOAD_DATE           ,  -- is_load_timestamp
    LOAD_CYCLE_ID       ,  -- is_load_cycle_id
    DELETE_FLAG         ,  -- is_delete_flag
    ACCT_DATE           ,  -- is_other_attr
    ASSOCIATED_TM_ID    ,  -- is_other_attr
    ATTACHMENT_ID       ,  -- is_other_attr
    AUDIT               ,  -- is_other_attr
    CREATED             ,  -- is_other_attr
    CUSTOM_113          ,  -- is_other_attr
    CUSTOM_114          ,  -- is_other_attr
    DATE_APPROVED       ,  -- is_other_attr
    DATE_ARCHIVED       ,  -- is_other_attr
    DATE_END            ,  -- is_other_attr
    DATE_START          ,  -- is_other_attr
    DATE_SUBMITTED      ,  -- is_other_attr
    DEFAULT_CATEGORY    ,  -- is_other_attr
    DEFAULT_CUSTOMER    ,  -- is_other_attr
    DEFAULT_PAYROLL_TYPE,  -- is_other_attr
    DEFAULT_PER_ROW     ,  -- is_other_attr
    DEFAULT_PROJECT     ,  -- is_other_attr
    DEFAULT_TASK        ,  -- is_other_attr
    DEFAULT_TIMETYPE    ,  -- is_other_attr
    DELETED             ,  -- is_other_attr
    DURATION            ,  -- is_other_attr
    EXPORTED            ,  -- is_other_attr
    HISTORY             ,  -- is_other_attr
    NAME                ,  -- is_other_attr
    NOTES               ,  -- is_other_attr
    PARENT_TIMESHEET_ID ,  -- is_other_attr
    START_END_MONTH_TS  ,  -- is_other_attr
    STATUS              ,  -- is_other_attr
    SUBMIT_WARNING      ,  -- is_other_attr
    THIN_CLIENT_ID      ,  -- is_other_attr
    TOTAL               ,  -- is_other_attr
    UNSAVED_DATA        ,  -- is_other_attr
    UPDATED             ,  -- is_other_attr
    USER_ID             ,  -- is_other_attr
    _FIVETRAN_ACTIVE    ,  -- is_other_attr
    _FIVETRAN_END       ,  -- is_other_attr
    _FIVETRAN_START     ,  -- is_other_attr
    _FIVETRAN_TRANS        -- is_other_attr
    ,
    ROW_NUMBER() OVER (
        PARTITION BY TIMESHEET_HKEY
        ORDER BY LOAD_DATE DESC
    ) AS row_num
FROM {{ source('eli_dv_rv', 'sat_oa_timesheet') }}
)

SELECT * EXCLUDE (row_num)
FROM RANKED_RECORDS
WHERE row_num = 1
AND DELETE_FLAG = 'N'
